CREATE TABLE p_approval_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),required INTEGER NOT NULL CHECK(required IN (0,1)),default_role TEXT NOT NULL CHECK(default_role IN ('owner','admin','manager')),version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE p_approval_rules(id TEXT PRIMARY KEY,name TEXT NOT NULL,position INTEGER NOT NULL,condition TEXT NOT NULL,approvers TEXT NOT NULL);
CREATE TABLE p_approval_decisions(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES p_proposals(id),revision INTEGER NOT NULL,plan TEXT NOT NULL,step TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES oa_operators(id),approver_index INTEGER NOT NULL CHECK(approver_index>=0),decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')),note TEXT NOT NULL,occurred_at INTEGER NOT NULL,UNIQUE(proposal_id,revision,plan,step,actor_id));
